package ru.local.jarvis;
import android.app.*;import android.app.job.*;import android.content.*;import android.os.*;import org.json.*;import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;

/** Durable server inbox -> stable local notification IDs -> acknowledgement. */
public final class InboxSync extends JobService {
 static final AtomicBoolean busy=new AtomicBoolean(false);static final String CHANNEL="jarvis_updates";
 static void schedule(Context c){JobScheduler scheduler=c.getSystemService(JobScheduler.class);scheduler.schedule(new JobInfo.Builder(9274,new ComponentName(c,InboxSync.class)).setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY).setPeriodic(15*60*1000).setPersisted(true).build());}
 static void poll(Context c){if(!busy.compareAndSet(false,true))return;try{NotificationManager manager=c.getSystemService(NotificationManager.class);manager.createNotificationChannel(new NotificationChannel(CHANNEL,"Джарвис · сводки и события",NotificationManager.IMPORTANCE_DEFAULT));if(!manager.areNotificationsEnabled()||manager.getNotificationChannel(CHANNEL).getImportance()==NotificationManager.IMPORTANCE_NONE)return;JSONObject response=Net.call(c,"/inbox/poll",null);JSONArray items=response.optJSONArray("items"),ack=new JSONArray();if(items==null)return;android.content.SharedPreferences seen=c.getSharedPreferences("inbox_seen",0);for(int i=0;i<items.length()&&i<20;i++){JSONObject item=items.getJSONObject(i);String id=item.getString("id");if(!id.matches("[a-f0-9]{32}"))continue;if(!seen.getBoolean(id,false)){PendingIntent open=PendingIntent.getActivity(c,0,new Intent(c,Main.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);manager.notify(id,62,new Notification.Builder(c,CHANNEL).setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle(item.getString("title")).setContentText(item.getString("body")).setStyle(new Notification.BigTextStyle().bigText(item.getString("body"))).setContentIntent(open).setAutoCancel(true).setVisibility(Notification.VISIBILITY_PRIVATE).build());if(!seen.edit().putBoolean(id,true).commit())continue;}ack.put(id);}if(ack.length()>0)Net.call(c,"/inbox/ack",new JSONObject().put("ids",ack));}catch(Exception e){android.util.Log.w("JarvisInbox","sync_failed_"+e.getClass().getSimpleName());}finally{busy.set(false);}}
 static void soon(Context c){new Thread(()->poll(c.getApplicationContext()),"JarvisInbox").start();}
 public boolean onStartJob(JobParameters params){new Thread(()->{poll(this);jobFinished(params,false);},"JarvisInboxJob").start();return true;}
 public boolean onStopJob(JobParameters params){return true;}
}
